from rcb_client import Robot
import numpy as np
r=Robot(); o=r.get_obs(cameras=['practice_cam','scene_cam','side_cam'],depth=True,video='frames')
for c in ['practice_cam','scene_cam','side_cam']:
 print('\n',c,'intr',o.meta['cameras'][c]['intrinsic_cv'],'\nextr',o.meta['cameras'][c]['extrinsic_cv'])
 im=o.last[c]; d=o.last_depth[c]
 if c=='scene_cam':
  gray=im.mean(axis=2); m=gray<50
  # bounding coords and candidate components via BFS
  H,W=m.shape; seen=np.zeros((H,W),bool); comps=[]
  for yy,xx in zip(*np.where(m & ~seen)):
   if seen[yy,xx]: continue
   todo=[(yy,xx)]; seen[yy,xx]=1; pts=[]
   while todo:
    y,x=todo.pop(); pts.append((y,x))
    for y2,x2 in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=y2<H and 0<=x2<W and m[y2,x2] and not seen[y2,x2]: seen[y2,x2]=1; todo.append((y2,x2))
   if len(pts)>4: comps.append(pts)
  for pts in sorted(comps,key=len,reverse=True)[:20]:
   ar=np.array(pts); y0,x0=ar.min(axis=0); y1,x1=ar.max(axis=0); center=ar.mean(axis=0); md=np.median(d[ar[:,0],ar[:,1]])
   print('darkcc box',x0,y0,x1-x0+1,y1-y0+1,len(pts),'center_yx',center,'depth',md)
  for y in [130,140,150,160,170,180,190]:
   print('row',y,[(x,int(gray[y,x]),round(float(d[y,x]),4)) for x in [280,300,310,320,330,340,360]])
